package cn.pawday.integration;
import cn.pawday.common.Api.Failure;
import cn.pawday.common.IdempotentCommandExecutor;
import cn.pawday.identity.*;
import cn.pawday.audit.AuditWriter;
import cn.pawday.outbox.OutboxWriter;
import cn.pawday.pilot.PilotPolicy;
import cn.pawday.publishing.PublishingSupport;
import static cn.pawday.publishing.PublishingSupport.*;
import jakarta.servlet.http.HttpServletRequest;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;
/** Synthetic-only inventory source. No browser endpoint accepts quantities, watermarks or provider results. */
@Service public class IntegrationInventoryService {
 private final PublishingSupport p;private final IntegrationPolicy policy;private final PilotPolicy pilot;private final AccessGuard guard;private final AuthService auth;
 private final IdempotentCommandExecutor commands;private final AuditWriter audit;private final OutboxWriter outbox;private final TransactionTemplate tx;private final Clock clock;
 public IntegrationInventoryService(PublishingSupport p,IntegrationPolicy policy,PilotPolicy pilot,AccessGuard guard,AuthService auth,IdempotentCommandExecutor commands,AuditWriter audit,OutboxWriter outbox,TransactionTemplate tx,Clock clock){this.p=p;this.policy=policy;this.pilot=pilot;this.guard=guard;this.auth=auth;this.commands=commands;this.audit=audit;this.outbox=outbox;this.tx=tx;this.clock=clock;}
 private void gate(){policy.requireEnabled();if(pilot.paused())throw new Failure(503,"PILOT_PAUSED");}
 private void staff(Actor a,UUID store,String permission){gate();permission(a,Actor.Realm.MERCHANT,permission);if(p.db.queryForObject("SELECT count(*) FROM principal_role pr JOIN role_permission rp ON rp.role_id=pr.role_id JOIN permission x ON x.id=rp.permission_id JOIN identity_principal i ON i.id=pr.principal_id JOIN auth_session s ON s.principal_id=i.id WHERE pr.principal_id=? AND pr.realm='MERCHANT' AND i.status='ACTIVE' AND s.id=? AND s.revoked_at IS NULL AND s.expires_at>? AND x.code=?",Integer.class,a.principalId(),a.sessionId(),now(),permission)==0)throw new Failure(403,"PERMISSION_DENIED");guard.store(a,store);p.one("SELECT s.id FROM merchant_store s JOIN merchant m ON m.id=s.merchant_id WHERE s.id=? AND s.merchant_id=? AND m.status='ACTIVE'",store,a.merchantId());}
 private Timestamp now(){return Timestamp.from(clock.instant());}
 private String testText(Object raw){String v=text(raw,110);if(!v.matches("TEST_ONLY_[A-Za-z0-9_.:-]{1,100}"))throw new Failure(400,"SYNTHETIC_EVIDENCE_REQUIRED");return v;}
 private void evidence(Object raw){if(!(raw instanceof List<?> rows)||rows.isEmpty()||rows.size()>10)throw new Failure(400,"SYNTHETIC_EVIDENCE_REQUIRED");for(Object x:rows){if(!(x instanceof Map<?,?> m)||!m.keySet().equals(Set.of("kind","reference"))||!"TEST_SCENARIO".equals(m.get("kind")))throw new Failure(400,"SYNTHETIC_EVIDENCE_REQUIRED");testText(m.get("reference"));}}
 private Map<String,Object> connection(UUID store,UUID id,boolean write){return p.one("SELECT * FROM integration_connections WHERE id=? AND store_id=?"+(write?" FOR UPDATE":""),id,store);}
 private Map<String,Object> connView(UUID id){var v=p.view(p.one("SELECT id,merchant_id,store_id,label,mode,inventory_basis,state,version,true AS simulated FROM integration_connections WHERE id=?",id));return v;}
 private Map<String,Object> mapView(UUID id){return p.view(p.one("SELECT id,connection_id,offer_id,external_sku,external_warehouse,unit,state,version,true AS simulated FROM integration_mappings WHERE id=?",id));}
 private Map<String,Object> mapping(UUID conn,UUID id){var m=p.one("SELECT * FROM integration_mappings WHERE id=? AND connection_id=? FOR UPDATE",id,conn);p.one("SELECT id FROM offers WHERE id=? FOR UPDATE",m.get("offer_id"));p.one("SELECT * FROM inventory_balances WHERE offer_id=? FOR UPDATE",m.get("offer_id"));return m;}
 private Map<String,Object> event(UUID conn,UUID id){return p.one("SELECT * FROM integration_inventory_events WHERE id=? AND connection_id=?",id,conn);}
 private void record(Actor a,String action,UUID id,HttpServletRequest r){audit.write(a,action,"ERP_WMS_SYNTHETIC",id.toString(),Map.of(),Map.of("simulated",true),r);}
 public List<Map<String,Object>> connections(Actor a,UUID store,UUID after,int size){staff(a,store,"integration.read");limit(size);return p.db.queryForList("SELECT id FROM integration_connections WHERE store_id=? AND id>? ORDER BY id LIMIT ?",store,after,size+1).stream().map(r->connView((UUID)r.get("id"))).toList();}
 public Map<String,Object> create(Actor a,UUID store,Map<String,Object>b,String key,String proof,HttpServletRequest r){staff(a,store,"integration.manage");fields(b,"label","mode","inventory_basis","evidence_refs");String label=testText(b.get("label"));evidence(b.get("evidence_refs"));if(!"SIMULATED_TEST".equals(b.get("mode"))||!"DEDICATED_REMAINING_AFTER_WATERMARK".equals(b.get("inventory_basis")))throw new Failure(400,"VALIDATION_ERROR");
  return commands.command(a,"integration.create:"+store,key,b,()->{staff(a,store,"integration.manage");auth.consumeProof(a,"integration.manage",proof);UUID id=UUID.randomUUID();p.db.update("INSERT INTO integration_connections(id,merchant_id,store_id,label,created_by,created_at) VALUES (?,?,?,?,?,?)",id,a.merchantId(),store,label,a.principalId(),now());record(a,"integration.manage",id,r);outbox.append("INTEGRATION",id.toString(),"IntegrationConnectionChanged",1,Map.of("connection_id",id,"version",0),null);return connView(id);});
 }
 public Map<String,Object> state(Actor a,UUID store,UUID conn,Map<String,Object>b,String match,String key,String proof,HttpServletRequest r){staff(a,store,"integration.manage");connection(store,conn,false);fields(b,"state","reason_code");String state=text(b.get("state"),8);if(!("ACTIVE".equals(state)&&"TEST_SCENARIO_START".equals(b.get("reason_code"))||"PAUSED".equals(state)&&"OPERATOR_PAUSE".equals(b.get("reason_code"))))throw new Failure(400,"VALIDATION_ERROR");long v=version(match);
  return commands.command(a,"integration.state:"+conn,key,Map.of("body",b,"version",v),()->{staff(a,store,"integration.manage");var c=connection(store,conn,true);sameVersion(c,v);staff(a,store,"integration.manage");if(state.equals(c.get("state")))throw new Failure(409,"INTEGRATION_STATE_CONFLICT");auth.consumeProof(a,"integration.manage",proof);p.db.update("UPDATE integration_connections SET state=?,version=version+1 WHERE id=?",state,conn);record(a,"integration.manage",conn,r);outbox.append("INTEGRATION",conn.toString(),"IntegrationConnectionChanged",1,Map.of("connection_id",conn,"version",v+1),null);return connView(conn);});
 }
 public List<Map<String,Object>> mappings(Actor a,UUID store,UUID conn,UUID after,int size){staff(a,store,"integration.read");connection(store,conn,false);limit(size);return p.db.queryForList("SELECT id FROM integration_mappings WHERE connection_id=? AND id>? ORDER BY id LIMIT ?",conn,after,size+1).stream().map(r->mapView((UUID)r.get("id"))).toList();}
 public Map<String,Object> bind(Actor a,UUID store,UUID conn,Map<String,Object>b,String match,String key,String proof,HttpServletRequest r){staff(a,store,"integration.mapping.write");connection(store,conn,false);fields(b,"offer_id","external_sku","external_warehouse","unit","evidence_refs");UUID offer=id(b.get("offer_id"));String sku=testText(b.get("external_sku")),warehouse=testText(b.get("external_warehouse"));evidence(b.get("evidence_refs"));if(!"PIECE".equals(b.get("unit")))throw new Failure(400,"VALIDATION_ERROR");long v=version(match);
  return commands.command(a,"integration.bind:"+conn,key,Map.of("body",b,"version",v),()->{staff(a,store,"integration.mapping.write");var c=connection(store,conn,true);sameVersion(c,v);if(!"PAUSED".equals(c.get("state")))throw new Failure(409,"INTEGRATION_MAPPING_REQUIRES_PAUSE");var o=p.one("SELECT * FROM offers WHERE id=? AND merchant_id=? AND store_id=? FOR UPDATE",offer,a.merchantId(),store);if("DELISTED".equals(o.get("sale_status")))throw new Failure(409,"OFFER_NOT_EDITABLE");var stock=p.one("SELECT * FROM inventory_balances WHERE offer_id=? FOR UPDATE",offer);
   if(number(stock.get("on_hand_qty"))!=0||number(stock.get("reserved_qty"))!=0||!p.db.queryForList("SELECT i.id FROM order_items i JOIN suborders s ON s.id=i.suborder_id WHERE i.offer_id=? AND s.fulfillment_status NOT IN ('CANCELLED','COMPLETED') LIMIT 1",offer).isEmpty())throw new Failure(409,"INTEGRATION_BOOTSTRAP_REQUIRES_EMPTY_STOCK");
   if(Boolean.TRUE.equals(p.db.queryForObject("SELECT integration_bootstrap_has_open_responsibility(?)",Boolean.class,offer)))throw new Failure(409,"INTEGRATION_BOOTSTRAP_OPEN_RESPONSIBILITY");
   if(!p.db.queryForList("SELECT id FROM integration_mappings WHERE state='ACTIVE' AND (offer_id=? OR connection_id=? AND external_sku=? AND external_warehouse=?)",offer,conn,sku,warehouse).isEmpty())throw new Failure(409,"INTEGRATION_MAPPING_IN_USE");
   staff(a,store,"integration.mapping.write");auth.consumeProof(a,"integration.mapping.write",proof);UUID id=UUID.randomUUID();long seq=p.db.queryForObject("SELECT coalesce(max(sequence),0) FROM integration_stock_movements WHERE offer_id=?",Long.class,offer);
   p.db.update("INSERT INTO integration_mappings(id,connection_id,offer_id,external_sku,external_warehouse,unit,epoch_sequence,epoch_inventory_version,created_by,created_at) VALUES (?,?,?,?,?,'PIECE',?,?,?,?)",id,conn,offer,sku,warehouse,seq,stock.get("version"),a.principalId(),now());record(a,"integration.mapping.write",id,r);outbox.append("INTEGRATION",conn.toString(),"IntegrationMappingChanged",1,Map.of("connection_id",conn,"mapping_id",id),null);return mapView(id);});
 }
 public Map<String,Object> retire(Actor a,UUID store,UUID conn,UUID id,Map<String,Object>b,String match,String key,String proof,HttpServletRequest r){staff(a,store,"integration.mapping.write");connection(store,conn,false);fields(b,"state","reason_code");if(!"RETIRED".equals(b.get("state"))||!"TEST_SCENARIO_RETIRED".equals(b.get("reason_code")))throw new Failure(400,"VALIDATION_ERROR");long v=version(match);
  return commands.command(a,"integration.retire:"+id,key,Map.of("body",b,"version",v),()->{staff(a,store,"integration.mapping.write");connection(store,conn,true);var m=mapping(conn,id);sameVersion(m,v);if(!"ACTIVE".equals(m.get("state")))throw new Failure(409,"INTEGRATION_MAPPING_RETIRED");long unresolved=p.db.queryForObject("SELECT count(*) FROM integration_inventory_events e WHERE e.mapping_id=? AND e.external_version>coalesce((SELECT max(ev.external_version) FROM integration_stock_applications x JOIN integration_inventory_events ev ON ev.id=x.event_id WHERE ev.mapping_id=?),0)",Long.class,id,id);if(unresolved>0)throw new Failure(409,"INTEGRATION_RESPONSIBILITY_OPEN");staff(a,store,"integration.mapping.write");auth.consumeProof(a,"integration.mapping.write",proof);p.db.update("UPDATE integration_mappings SET state='RETIRED',version=version+1 WHERE id=?",id);record(a,"integration.mapping.write",id,r);outbox.append("INTEGRATION",conn.toString(),"IntegrationMappingChanged",1,Map.of("connection_id",conn,"mapping_id",id),null);return mapView(id);});
 }
 public List<Map<String,Object>> events(Actor a,UUID store,UUID conn,UUID after,int size){staff(a,store,"integration.read");connection(store,conn,false);limit(size);return p.db.queryForList("SELECT *,true AS simulated FROM integration_inventory_events WHERE connection_id=? AND id>? ORDER BY id LIMIT ?",conn,after,size+1).stream().map(p::view).toList();}
 @SuppressWarnings("unchecked") private Map<String,Object> context(UUID event){return p.json.readValue(p.one("SELECT integration_inventory_context(?) AS value",event).get("value").toString(),Map.class);}
 private String hash(Map<String,Object> ctx){return p.db.queryForObject("SELECT encode(digest(?::jsonb::text,'sha256'),'hex')",String.class,p.json.writeValueAsString(ctx));}
 private Map<String,Object> previewView(UUID id){var row=p.one("SELECT * FROM integration_stock_previews WHERE id=?",id);Map<String,Object> ctx=p.json.readValue(row.get("snapshot").toString(),Map.class);var v=new LinkedHashMap<String,Object>();for(String k:List.of("event_id","mapping_id","inventory_version","local_sequence","on_hand_qty","reserved_qty","target_on_hand_qty","delta_qty","eligible","blocked_reasons"))v.put(k,ctx.get(k));for(String k:List.of("id","snapshot_sha256","created_at","expires_at"))v.put(k,row.get(k));v.put("simulated",true);return p.view(v);}
 public Map<String,Object> preview(Actor a,UUID store,UUID conn,UUID event,Map<String,Object>b,String key,HttpServletRequest r){staff(a,store,"integration.stock.assess");connection(store,conn,false);fields(b);
  return commands.command(a,"integration.preview:"+event,key,b,()->{staff(a,store,"integration.stock.assess");connection(store,conn,true);var e=event(conn,event);mapping(conn,(UUID)e.get("mapping_id"));staff(a,store,"integration.stock.assess");var ctx=context(event);UUID id=UUID.randomUUID();Timestamp created=now();p.db.update("INSERT INTO integration_stock_previews VALUES (?,?,?::jsonb,?,?,?,?)",id,event,p.json.writeValueAsString(ctx),hash(ctx),a.principalId(),created,Timestamp.from(created.toInstant().plusSeconds(300)));record(a,"integration.stock.assess",id,r);return previewView(id);});
 }
 private Map<String,Object> applicationView(UUID id){return p.view(p.one("SELECT id,preview_id,event_id,offer_id,before_on_hand_qty,resulting_on_hand_qty,reserved_qty,resulting_inventory_version,true AS simulated FROM integration_stock_applications WHERE id=?",id));}
 public Map<String,Object> apply(Actor a,UUID store,UUID conn,UUID preview,Map<String,Object>b,String key,String proof,HttpServletRequest r){staff(a,store,"integration.stock.apply");connection(store,conn,false);fields(b,"accepted_snapshot_sha256");String accepted=text(b.get("accepted_snapshot_sha256"),64);if(!accepted.matches("[0-9a-f]{64}"))throw new Failure(400,"VALIDATION_ERROR");
  return commands.command(a,"integration.apply:"+preview,key,b,()->{staff(a,store,"integration.stock.apply");connection(store,conn,true);var snap=p.one("SELECT p.* FROM integration_stock_previews p JOIN integration_inventory_events e ON e.id=p.event_id WHERE p.id=? AND p.created_by=? AND e.connection_id=?",preview,a.principalId(),conn);var e=event(conn,(UUID)snap.get("event_id"));var m=mapping(conn,(UUID)e.get("mapping_id"));
   staff(a,store,"integration.stock.apply");if(!((Timestamp)snap.get("expires_at")).toInstant().isAfter(clock.instant()))throw new Failure(409,"INTEGRATION_PREVIEW_EXPIRED");if(!p.db.queryForList("SELECT id FROM integration_stock_applications WHERE preview_id=? OR event_id=?",preview,e.get("id")).isEmpty())throw new Failure(409,"INTEGRATION_EVENT_ALREADY_APPLIED");
   var ctx=context((UUID)e.get("id"));if(!accepted.equals(snap.get("snapshot_sha256"))||!accepted.equals(hash(ctx)))throw new Failure(409,"INTEGRATION_PREVIEW_STALE");if(!Boolean.TRUE.equals(ctx.get("eligible")))throw new Failure(409,"INTEGRATION_STOCK_BLOCKED");auth.consumeProof(a,"integration.stock.apply",proof);UUID id=UUID.randomUUID();p.db.update("INSERT INTO integration_stock_applications VALUES (?,?,?,?,?,?,?,?,?,?)",id,preview,e.get("id"),m.get("offer_id"),ctx.get("on_hand_qty"),ctx.get("target_on_hand_qty"),ctx.get("reserved_qty"),number(ctx.get("inventory_version"))+1,a.principalId(),now());
   record(a,"integration.stock.apply",id,r);UUID sku=(UUID)p.one("SELECT sku_id FROM offers WHERE id=?",m.get("offer_id")).get("sku_id");outbox.append("OFFER",m.get("offer_id").toString(),"IntegrationInventoryApplied",1,Map.of("offer_id",m.get("offer_id"),"sku_id",sku,"application_id",id,"inventory_version",number(ctx.get("inventory_version"))+1),null);return applicationView(id);});
 }
 public List<Map<String,Object>> applications(Actor a,UUID store,UUID conn,UUID after,int size){staff(a,store,"integration.read");connection(store,conn,false);limit(size);return p.db.queryForList("SELECT x.id FROM integration_stock_applications x JOIN integration_inventory_events e ON e.id=x.event_id WHERE e.connection_id=? AND x.id>? ORDER BY x.id LIMIT ?",conn,after,size+1).stream().map(row->applicationView((UUID)row.get("id"))).toList();}
 /** Package-scoped ingestion, invoked only by the server test adapter or internal integration tests. */
 UUID acceptFixtureEvent(UUID store,UUID conn,UUID mapping,String externalKey,long extVersion,long qty,long ack,UUID acknowledgement){
  gate();if(!externalKey.matches("TEST_ONLY_[A-Za-z0-9_.:-]{1,100}")||extVersion<1||extVersion>1000000000||qty<0||qty>1000000000||ack<0)throw new Failure(400,"VALIDATION_ERROR");
  return tx.execute(s->{var c=connection(store,conn,true);var m=mapping(conn,mapping);if(!"ACTIVE".equals(c.get("state"))||!"ACTIVE".equals(m.get("state")))throw new Failure(409,"INTEGRATION_INACTIVE");String digest=p.db.queryForObject("SELECT integration_event_hash(?,?,?,?,?,?,?)",String.class,mapping,m.get("version"),externalKey,extVersion,qty,ack,acknowledgement);
   var prior=p.db.queryForList("SELECT id,payload_sha256 FROM integration_inventory_events WHERE connection_id=? AND external_event_id=?",conn,externalKey);if(!prior.isEmpty()){if(!digest.equals(prior.getFirst().get("payload_sha256")))throw new Failure(409,"INTEGRATION_EVENT_IDENTITY_CONFLICT");return (UUID)prior.getFirst().get("id");}
   if(!p.db.queryForList("SELECT id FROM integration_inventory_events WHERE mapping_id=? AND external_version=?",mapping,extVersion).isEmpty())throw new Failure(409,"INTEGRATION_EXTERNAL_VERSION_CONFLICT");UUID id=UUID.randomUUID();p.db.update("INSERT INTO integration_inventory_events VALUES (?,?,?,?,?,?,?,?,?,?,?)",id,conn,mapping,m.get("version"),externalKey,extVersion,qty,ack,acknowledgement,digest,now());record(null,"integration.fixture.receive",id,null);outbox.append("INTEGRATION",conn.toString(),"IntegrationInventoryEventReceived",1,Map.of("event_id",id,"mapping_id",mapping),null);return id;});
 }
}
